                  {{- end -}}
                {{- else -}}
                  <tr><td colspan="2"><em>No test details available</em></td></tr>
                {{- end -}}
              </table>
            </td>
          </tr>
        {{- end -}}
      {{- end -}}
    {{- end -}}

    {{- /* Stable channel tests */ -}}
    {{- range $comp, $items := $grouped -}}
