        <td></td>
        <td>{{ $subcommand.description }}</td>
      </tr>
          {{- if $subcommand.flags }}
            {{- range $flagkey, $flag := $subcommand.flags }}
      <tr>
        <td></td>
        <td>{{ $flag.name }}</td>
        <td>{{ $flag.description }}</td>
      </tr>
            {{- end }}
