        {{- else }}
        <td></td>
        {{- end }}
        <td></td>
        <td>{{ $flag.name }}</td>
        <td>{{ $flag.description }}</td>
      </tr>
        {{- end }}
      {{- end }}

      <!-- Output subcommands -->
      {{- if $subcommand.subcommands }}
