        {{- $subcommand_page := site.GetPage $subcommand_path -}}
        <td>{{ if $subcommand_page }}<a href="{{ $subcommand_page.RelPermalink }}">{{ $subcommand.name }}</a>{{ else }}{{ $subcommand.name }}{{ end }}</td>
        {{- $first = false }}
        {{- else }}
        <td></td>
        {{- end }}
        {{- $subsubcommand_path := printf "reference/references/mesheryctl/%s/%s/%s" $command_name $subkey $subsubkey -}}
        {{- $subsubcommand_page := site.GetPage $subsubcommand_path -}}
        <td>{{ if $subsubcommand_page }}<a href="{{ $subsubcommand_page.RelPermalink }}">{{ $subsubcommand.name }}</a>{{ else }}{{ $subsubcommand.name }}{{ end }}</td>
        <td></td>
        <td>{{ $subsubcommand.description }}</td>
