{{- /*
  Renders a list of model category names, each with a parenthetical count of
  the models in that category (e.g. "Provisioning (69)"). Counts are derived
  from the `integrations-category` param on each model page, so they stay
  accurate as models are added, removed, or recategorized. Categories are
  ordered by count (descending) so the largest are surfaced first.

  Category names are plain labels, not links: the models index is a single
  alphabetized page with no per-category filtering, so a category link would
  resolve to the same unfiltered page for every category. The "See all models"
  link in the parent list provides navigation to that index.
*/ -}}
{{- $models := where site.RegularPages ".File.Dir" "like" `^extensions/models/` -}}
{{- $groups := $models.GroupByParam "integrations-category" -}}
{{- $categories := slice -}}
{{- range $groups -}}
  {{- if .Key -}}
    {{- $categories = $categories | append (dict "name" .Key "count" (len .Pages)) -}}
  {{- end -}}
{{- end -}}
{{- $categories = sort $categories "count" "desc" -}}
{{- range $categories -}}
<li>{{ .name }} ({{ .count }})</li>
{{- end -}}

{{- $tag := .Get "tag" | default "meshery" -}}
{{- $data := index hugo.Data.discuss $tag -}}

<div class="related-discussions">
  <h3>Recent Discussions with "{{ $tag }}" Tag</h3>

  {{- if and $data $data.topic_list $data.topic_list.topics -}}
    <ul>
      {{- range first 8 $data.topic_list.topics -}}
        <li>
          <a href="https://discuss.meshery.io/t/{{ .slug }}/{{ .id }}" target="_blank" rel="noopener noreferrer">
            {{ .title }}
          </a>
        </li>
      {{- end -}}
    </ul>
  {{- end -}}

  <p>
    <a href="https://discuss.meshery.io/tag/{{ $tag }}" target="_blank" rel="noopener noreferrer">
      View all discussions tagged with <code>{{ $tag }}</code>
    </a>
  </p>
</div>

{{- /* Get section parameter from shortcode */ -}}
{{- $section := .Get "section" -}}

{{- /* If no section provided, try to detect from current page */ -}}
{{- if not $section -}}
  {{- $section = .Page.Section -}}
{{- end -}}

{{- /* Build the landing page URL to exclude */ -}}
{{- $sectionURL := printf "/%s/" $section -}}

{{- /* Pages to exclude from auto-listing */ -}}
{{- $excludePages := slice "quick-start" "faq" -}}

{{- /* Load all pages from the specified section - only 1 level deep */ -}}
{{- $pages := slice -}}
{{- range site.AllPages -}}
  {{- if and (strings.Contains .Path $section) (ne .Kind "taxonomy") (ne .Kind "taxonomyTerm") -}}
    {{- /* Skip pages marked to hide from section listing */ -}}
    {{- if .Params.hide_homepage -}}
      {{- continue -}}
    {{- end -}}
    {{- /* Exclude the landing page of the current section */ -}}
    {{- if eq .RelPermalink $sectionURL -}}
      {{- continue -}}
    {{- end -}}
    {{- /* Count the path depth to ensure only 1 level deep */ -}}
    {{- $sectionParts := strings.Split $section "/" -}}
    {{- $pageParts := strings.Split .Path "/" -}}
    {{- /* Only include if page is exactly one level deeper than section */ -}}
    {{- if and (gt (len $pageParts) (len $sectionParts)) (le (len $pageParts) (add (len $sectionParts) 2)) -}}
      {{- /* Skip excluded pages by checking the last path segment */ -}}
      {{- $shouldExclude := false -}}
      {{- $pagePathSegment := index $pageParts (sub (len $pageParts) 1) -}}
      {{- range $excludePages -}}
        {{- if eq $pagePathSegment . -}}
          {{- $shouldExclude = true -}}
        {{- end -}}
      {{- end -}}
      {{- if not $shouldExclude -}}
        {{- $pages = $pages | append . -}}
      {{- end -}}
    {{- end -}}
  {{- end -}}
{{- end -}}

{{- /* Sort pages by title */ -}}
{{- $pages = sort $pages "Title" -}}

{{- if $pages -}}
  {{- range $pages -}}
<li>
  <a href="{{ .RelPermalink }}">{{ .Title }}</a>
  {{- if .Params.description -}}
    <span> - {{ .Params.description }}</span>
  {{- end -}}
</li>
  {{- end -}}
{{- else -}}
<li><em>No pages found in this section.</em></li>
{{- end -}}

{{- $group := .Get "id" -}}
{{- $level := int (.Get "level" | default "1") -}}
{{- if not $group -}}
  {{- errorf "The %q shortcode requires an 'id' argument: see %s" .Name .Position -}}
{{- end -}}

{{- /* Ensure each tabs shortcode on a page gets an isolated radio group. */ -}}
{{- $instance := add (default 0 (.Page.Scratch.Get "tabs-instance-counter")) 1 -}}
{{- .Page.Scratch.Set "tabs-instance-counter" $instance -}}

{{- $blocks := split (trim .InnerDeindent "\n\r\t ") "<!-- tab -->" -}}
{{- $page := .Page -}}
<div class="tab-container tab-level-{{ $level }}{{ if gt $level 1 }} tab-container--nested{{ end }}">
{{- $checked := false -}}
{{- $tabIndex := 0 -}}
{{- range $index, $raw := $blocks -}}
  {{- $block := trim $raw "\n\r\t " -}}
  {{- if ne $block "" -}}
    {{- $tabIndex = add $tabIndex 1 -}}
    {{- $parts := split $block "\n\n" -}}
    {{- $title := trim (index $parts 0) "\n\r\t " -}}
    {{- $titleParts := split $title "|" -}}
    {{- $tabTitle := trim (index $titleParts 0) " \n\r\t" -}}
    {{- $iconRaw := "" -}}
    {{- if gt (len $titleParts) 1 -}}
      {{- $iconRaw = trim (index $titleParts 1) " \n\r\t" -}}
    {{- end -}}
    {{- $content := "" -}}
    {{- if gt (len $parts) 1 -}}
      {{- $content = delimit (after 1 $parts) "\n\n" -}}
    {{- end -}}
    {{- $groupName := printf "%s-%d" $group $instance -}}
    {{- $tabID := printf "%s-%d" $groupName $tabIndex -}}
    {{- $contentID := printf "%s-content-%d" $groupName $tabIndex -}}
    <input id="{{ $tabID }}" type="radio" name="{{ $groupName }}"{{ if not $checked }} checked{{ end }}>
    <label for="{{ $tabID }}">
      {{- if ne $iconRaw "" -}}
        {{- if hasPrefix $iconRaw "fa" -}}
          <i class="{{ $iconRaw }}" aria-hidden="true"></i>
        {{- else -}}
          <i class="fa-icon" aria-hidden="true">{{ $iconRaw | safeHTML }}</i>
        {{- end -}}
      {{- end -}}
      {{ $tabTitle }}
    </label>
    <section class="tabbed" id="{{ $contentID }}">
      {{- $content | $page.RenderString -}}
    </section>
    {{- $checked = true -}}
  {{- end -}}
{{- end -}}
</div>

{{- $guides := where .Site.RegularPages ".Params.categories" "intersect" (slice "troubleshooting") }}
<ul>
{{- range $guides }}
{{- if ne .Kind "section" }}
    <li><a href="{{ .RelPermalink }}">{{ .Title }}</a></li>
{{- end }}
{{- end }}
</ul>

